import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:uuid/uuid.dart';import '../../models/app_models.dart';import '../../providers/app_state.dart';
class MedicinesScreen extends ConsumerWidget{const MedicinesScreen({super.key});@override Widget build(BuildContext c,WidgetRef ref){final list=ref.watch(medicinesProvider);return Scaffold(appBar:AppBar(title:const Text('Medicines')),floatingActionButton:FloatingActionButton(onPressed:()=>_edit(c,ref),child:const Icon(Icons.add)),body:list.isEmpty?const Center(child:Text('No medicines yet. Tap + to add one.')):ListView.builder(padding:const EdgeInsets.all(16),itemCount:list.length,itemBuilder:(_,i){final m=list[i];return Card(child:ListTile(leading:Checkbox(value:m.taken,onChanged:(_)=>ref.read(medicinesProvider.notifier).toggle(m.id)),title:Text(m.name),subtitle:Text('${m.dosage} • ${m.time} • ${m.foodTiming}\n${m.notes}'),isThreeLine:true,onTap:()=>_edit(c,ref,m),trailing:IconButton(icon:const Icon(Icons.delete),onPressed:()=>ref.read(medicinesProvider.notifier).delete(m.id))));}));}void _edit(BuildContext c,WidgetRef ref,[Medicine? old]){final name=TextEditingController(text:old?.name);final dose=TextEditingController(text:old?.dosage);final time=TextEditingController(text:old?.time??'8:00 AM');showDialog(context:c,builder:(_)=>AlertDialog(title:Text(old==null?'Add medicine':'Edit medicine'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Medicine name')),TextField(controller:dose,decoration:const InputDecoration(labelText:'Dosage')),TextField(controller:time,decoration:const InputDecoration(labelText:'Time'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),FilledButton(onPressed:(){ref.read(medicinesProvider.notifier).upsert(Medicine(id:old?.id??const Uuid().v4(),userId:'demo',name:name.text,dosage:dose.text,time:time.text));Navigator.pop(c);},child:const Text('Save'))]));}}
